-- Lot 002 : les 76 tags du contrat V3, avec leur definition.
--
-- Seuls les tags REELLEMENT UTILISES sont poses : un tag sans resultat est
-- une porte qui ouvre sur une piece vide. Les 28 deja en base sont mis a
-- jour, les 48 autres crees. Aucun n'est desactive ici — un tag V2 encore
-- porte par des cartes ecrites continue de servir.

begin;

drop table if exists lot_tags_v3;
create temporary table lot_tags_v3 as
select * from jsonb_to_recordset($raccourcia$[{"slug":"photographie","nom":"Photographie","definition":"Le rendu attendu imite une prise de vue réelle.","ordre":1},{"slug":"portrait","nom":"Portrait","definition":"Une personne est le sujet principal.","ordre":2},{"slug":"montage","nom":"Montage","definition":"Assemblage visuel ou effet ajouté à une scène.","ordre":3},{"slug":"lumiere","nom":"Lumière","definition":"Traitement lumineux au cœur du concept.","ordre":4},{"slug":"voyage","nom":"Voyage","definition":"Destination ou exploration d'un lieu.","ordre":5},{"slug":"fantasy","nom":"Fantasy","definition":"Univers fantastique et créatures imaginaires.","ordre":6},{"slug":"cinema","nom":"Cinema","definition":"Esthétique de film, plateau ou affiche.","ordre":7},{"slug":"illustration","nom":"Illustration","definition":"Rendu dessiné, peint ou graphiquement interprété.","ordre":8},{"slug":"nature","nom":"Nature","definition":"Paysage, végétation ou milieu naturel.","ordre":9},{"slug":"mode","nom":"Mode","definition":"Tenues, accessoires, essayage et éditorial vestimentaire.","ordre":10},{"slug":"schema","nom":"Schéma","definition":"Relations ou structures représentées de manière explicative.","ordre":11},{"slug":"technique","nom":"Technique","definition":"Données, mécanismes ou construction à respecter.","ordre":12},{"slug":"pedagogie","nom":"Pédagogie","definition":"But explicatif ou d'apprentissage.","ordre":13},{"slug":"produit","nom":"Produit","definition":"Objet ou service présenté comme sujet commercial.","ordre":14},{"slug":"typographie","nom":"Typographie","definition":"Texte organisé comme élément visuel essentiel.","ordre":15},{"slug":"humour","nom":"Humour","definition":"Situation ou narration comique.","ordre":16},{"slug":"souvenir","nom":"Souvenir","definition":"Objet visuel lié à un moment personnel.","ordre":17},{"slug":"ecommerce","nom":"E-commerce","definition":"Présentation pour une fiche produit ou une vente.","ordre":18},{"slug":"publicite","nom":"Publicité","definition":"Visuel destiné à communiquer une offre.","ordre":19},{"slug":"affiche","nom":"Affiche","definition":"Composition d'affiche, avec ou sans texte.","ordre":20},{"slug":"marque","nom":"Marque","definition":"Identité, cohérence ou univers de marque.","ordre":21},{"slug":"afrique","nom":"Afrique","definition":"Contexte africain explicitement choisi.","ordre":22},{"slug":"miniature","nom":"Miniature","definition":"Changement d'échelle ou décor miniature.","ordre":23},{"slug":"couverture","nom":"Couverture","definition":"Première page, pochette ou jaquette.","ordre":24},{"slug":"architecture","nom":"Architecture","definition":"Bâtiments, plans d'espace ou aménagements.","ordre":25},{"slug":"retro","nom":"Rétro","definition":"Évocation d'une période passée.","ordre":26},{"slug":"fond-ecran","nom":"Fond d'écran","definition":"Image conçue pour un écran personnel.","ordre":27},{"slug":"professionnel","nom":"Professionnel","definition":"Usage métier ou présentation professionnelle.","ordre":28},{"slug":"coupe","nom":"Coupe","definition":"Intérieur révélé par une section.","ordre":29},{"slug":"beaute","nom":"Beauté","definition":"Coiffure, maquillage, barbe, manucure ou apparence.","ordre":30},{"slug":"culture","nom":"Culture","definition":"Évocation documentée d'un patrimoine.","ordre":31},{"slug":"vues","nom":"Vues","definition":"Points de vue coordonnés du même sujet.","ordre":32},{"slug":"famille","nom":"Famille","definition":"Plusieurs proches ou un souvenir familial.","ordre":33},{"slug":"instagram","nom":"Instagram","definition":"Usage prévu dans une publication ou un carrousel Instagram.","ordre":34},{"slug":"animaux","nom":"Animaux","definition":"Animal comme sujet identifiable.","ordre":35},{"slug":"anime","nom":"Anime","definition":"Langage graphique de l'animation japonaise.","ordre":36},{"slug":"trois-d","nom":"3D","definition":"Rendu de volume ou maquette numérique assumé.","ordre":37},{"slug":"alimentation","nom":"Alimentation","definition":"Plat, ingrédient ou boisson.","ordre":38},{"slug":"peinture","nom":"Peinture","definition":"Touches, pigments et matière picturale visibles.","ordre":39},{"slug":"retouche","nom":"Retouche","definition":"Modification ou correction d'une image existante.","ordre":40},{"slug":"lifestyle","nom":"Lifestyle","definition":"Scène quotidienne ou portrait spontané.","ordre":41},{"slug":"collage","nom":"Collage","definition":"Assemblage de fragments photographiques ou de papier.","ordre":42},{"slug":"bd","nom":"BD","definition":"Narration organisée en cases et bulles.","ordre":43},{"slug":"surrealisme","nom":"Surréalisme","definition":"Élément impossible intégré volontairement.","ordre":44},{"slug":"cartoon","nom":"Cartoon","definition":"Personnages simplifiés à contours et aplats.","ordre":45},{"slug":"selfie","nom":"Selfie","definition":"Cadrage à bout de bras ou via un miroir.","ordre":46},{"slug":"packaging","nom":"Packaging","definition":"Emballage ou étiquette.","ordre":47},{"slug":"vue-eclatee","nom":"Vue éclatée","definition":"Composants séparés selon leur assemblage.","ordre":48},{"slug":"serie","nom":"Série","definition":"Plusieurs vues ou images cohérentes.","ordre":49},{"slug":"avatar","nom":"Avatar","definition":"Représentation personnelle utilisable comme identité visuelle ou personnage.","ordre":50},{"slug":"sport","nom":"Sport","definition":"Pratique, portrait ou ambiance sportive.","ordre":51},{"slug":"story","nom":"Story","definition":"Visuel vertical prévu pour une story.","ordre":52},{"slug":"barbie","nom":"Barbie","definition":"Carte explicitement située dans l'univers Barbie.","ordre":53},{"slug":"infographie","nom":"Infographie","definition":"Informations hiérarchisées en une composition graphique.","ordre":54},{"slug":"musique","nom":"Musique","definition":"Artiste, album ou univers musical.","ordre":55},{"slug":"aventure","nom":"Aventure","definition":"Exploration ou scène d'action non documentaire.","ordre":56},{"slug":"carrousel","nom":"Carrousel","definition":"Plusieurs images conçues pour être parcourues dans un ordre.","ordre":57},{"slug":"evenement","nom":"Événement","definition":"Annonce ou souvenir d'un événement.","ordre":58},{"slug":"fleurs","nom":"Fleurs","definition":"Fleurs comme élément majeur.","ordre":59},{"slug":"ia","nom":"IA","definition":"Visualisation de concepts d'intelligence artificielle.","ordre":60},{"slug":"luxe","nom":"Luxe","definition":"Direction esthétique sobre et raffinée.","ordre":61},{"slug":"naruto","nom":"Naruto","definition":"Carte explicitement située dans l'univers Naruto.","ordre":62},{"slug":"noir-blanc","nom":"Noir et blanc","definition":"Image volontairement monochrome.","ordre":63},{"slug":"pokemon","nom":"Pokémon","definition":"Carte avec un personnage ou un univers Pokémon.","ordre":64},{"slug":"reels","nom":"Reels","definition":"Couverture ou image fixe pour une vidéo courte.","ordre":65},{"slug":"simpsons","nom":"Les Simpson","definition":"Carte explicitement située dans l'univers Les Simpson.","ordre":66},{"slug":"south-park","nom":"South Park","definition":"Carte explicitement située dans l'univers South Park.","ordre":67},{"slug":"tiktok","nom":"TikTok","definition":"Image fixe prévue pour TikTok ; aucune vidéo implicite.","ordre":68},{"slug":"avant-apres","nom":"Avant / après","definition":"Comparaison explicite de deux états.","ordre":69},{"slug":"dragon-ball","nom":"Dragon Ball","definition":"Carte explicitement située dans l'univers Dragon Ball.","ordre":70},{"slug":"electronique","nom":"Électronique","definition":"Composants et circuits électriques ou électroniques.","ordre":71},{"slug":"figurine","nom":"Figurine","definition":"Sujet transformé en objet de collection ou en jouet.","ordre":72},{"slug":"ghibli","nom":"Studio Ghibli","definition":"Carte inspirée du langage visuel du Studio Ghibli.","ordre":73},{"slug":"one-piece","nom":"One Piece","definition":"Carte explicitement située dans l'univers One Piece.","ordre":74},{"slug":"science","nom":"Science","definition":"Contenu scientifique documenté.","ordre":75},{"slug":"stickers","nom":"Stickers","definition":"Découpes visuelles destinées à être réutilisées.","ordre":76}]$raccourcia$)
as x(slug text, nom text, definition text, ordre integer);

insert into public.tags (slug, name, groupe, description, is_active, sort_order)
select l.slug, l.nom, 'style'::public.tag_group, l.definition, true, l.ordre
from lot_tags_v3 l
on conflict (slug) do update
set name = excluded.name,
    description = excluded.description,
    is_active = true;

do $ctrl$
declare
  v_poses integer;
  v_sans_definition integer;
begin
  select count(*) into v_poses from lot_tags_v3 l join public.tags t on t.slug = l.slug;
  select count(*) into v_sans_definition
  from lot_tags_v3 l join public.tags t on t.slug = l.slug
  where coalesce(btrim(t.description), '') = '';

  if v_poses <> 76 then
    raise exception 'Lot 002 : % tags sur 76.', v_poses;
  end if;
  if v_sans_definition > 0 then
    raise exception 'Lot 002 : % tags sans definition.', v_sans_definition;
  end if;
  raise notice 'Referentiel V3 : % tags, tous definis.', v_poses;
end $ctrl$;

drop table lot_tags_v3;

commit;
